'use strict';

// MODULES //

var isColumnMajor = require( '@stdlib/ndarray/base/assert/is-column-major-string' );
var resolveLayout = require( '@stdlib/blas/base/layout-resolve-str' );
var isPow2 = require( '@stdlib/math/base/assert/uint32-is-pow2' );
var max = require( '@stdlib/math/base/special/fast/max' );
var format = require( '@stdlib/string/format' );
var ndarray = require( './ndarray.js' );


// MAIN //

/**
* Generates a Hadamard matrix.
*
* @param {(integer|string)} order - storage layout
* @param {NonNegativeInteger} N - number of rows and columns of the output matrix
* @param {Collection} out - output array
* @param {PositiveInteger} ldo - stride between successive contiguous vectors of the matrix `out` (a.k.a., leading dimension of the matrix `out`)
* @throws {TypeError} first argument must be a valid order
* @throws {RangeError} second argument must be a power of two
* @throws {RangeError} fourth argument must be a valid stride
* @returns {Collection} output matrix
*
* @example
* var out = [ 0.0, 0.0, 0.0, 0.0 ];
*
* ghadamard( 'row-major', 2, out, 2 );
* // out => [ 1.0, 1.0, 1.0, -1.0 ]
*/
function ghadamard( order, N, out, ldo ) {
	var iscm;
	var sa1;
	var sa2;
	var l;

	l = resolveLayout( order );
	if ( l === null ) {
		throw new TypeError( format( 'invalid argument. First argument must be a valid order. Value: `%s`.', order ) );
	}
	if ( ldo < max( 1, N ) ) {
		throw new RangeError( format( 'invalid argument. Fourth argument must be greater than or equal to max(1,%d). Value: `%d`.', N, ldo ) );
	}
	if ( N <= 0 ) {
		return out;
	}
	if ( !isPow2( N ) ) {
		throw new RangeError( format( 'invalid argument. Second argument must be a power of two. Value: `%d`.', N ) );
	}
	iscm = isColumnMajor( l );
	if ( iscm ) {
		sa1 = 1;
		sa2 = ldo;
	} else { // order === 'row-major'
		sa1 = ldo;
		sa2 = 1;
	}
	return ndarray( N, out, sa1, sa2, 0 );
}


// EXPORTS //

module.exports = ghadamard;
